/* eslint-disable react-hooks/set-state-in-effect, react-hooks/exhaustive-deps */
import { FormEvent, useEffect, useState } from 'react';
import {
  AlertTriangle, ArrowLeft, BadgeCheck, Boxes, CheckCircle2,
  ClipboardCheck, Copy, Download, ExternalLink, FileCheck2, FileImage, KeyRound, Link2,
  ListChecks, Plus, Printer, RefreshCw, Rocket, Search, Send, ShieldCheck, Sparkles, Upload,
  UserRoundCog, Wrench,
} from 'lucide-react';
import { utilidadesV15Api, type Row } from '@/services/utilidadesApi';
import { ErrorBox, Loading, Modal, SuccessBox, asArray, formatDate, text } from './UtilidadesCommon';
import { citationQaPresentation, isLivePublicationStatus, isLocalLabResourceUrl } from './citationBuilderResource';
import './utilidades-citation-builder-v24.css';

type Props = { locationId:number; locationName:string; onAction:(title:string,description:string)=>void };
type Tab = 'resumen'|'datos'|'directorios'|'submissions'|'acciones'|'evidencias'|'duplicados'|'historial';

const tabs: Array<[Tab,string]> = [
  ['resumen','Resumen'],['datos','Datos del negocio'],['directorios','Selección de directorios'],['submissions','Envíos'],
  ['acciones','Acciones requeridas'],['evidencias','Evidencias'],['duplicados','Duplicados'],['historial','Historial'],
];
const statusLabels:Record<string,string> = {
  draft:'Borrador',active:'Activa',paused:'Pausada',qa:'QA',completed:'Completada',cancelled:'Cancelada',
  preparing:'Preparar',ready:'Lista',submitted:'Enviada',verification:'Esperando verificación',action_required:'Requiere acción',
  live:'Activa',updated:'Actualizada',rejected:'Rechazada',replaced:'Reemplazada',
};
const phaseIcons:Record<string,React.ReactNode> = {
  preparation:<Wrench size={17}/>,submission:<Send size={17}/>,qa:<ClipboardCheck size={17}/>,live:<BadgeCheck size={17}/>,issues:<AlertTriangle size={17}/>,
};
function rows(value:unknown){ return asArray(value) as Row[]; }
function rec(value:unknown){ return value && typeof value==='object' && !Array.isArray(value) ? value as Row : {}; }
function n(value:unknown){ const x=Number(value); return Number.isFinite(x)?x:0; }
function pct(value:unknown){ return `${Math.max(0,Math.min(100,n(value)))}%`; }
function statusClass(value:unknown){ const v=String(value||''); if(['live','updated','completed','ready','active'].includes(v))return'ok'; if(['action_required','rejected','issues'].includes(v))return'bad'; if(['submitted','verification','qa'].includes(v))return'warn'; return'neutral'; }

const missingLabels:Record<string,string>={name:'Nombre',address:'Dirección',phone:'Teléfono',postcode:'Código postal',website:'Sitio web',email:'Email',contactName:'Contacto',primaryCategory:'Categoría principal',secondaryCategories:'Categorías secundarias',description:'Descripción',hours:'Horarios',services:'Servicios',paymentMethods:'Métodos de pago',socialProfiles:'Perfiles sociales',logoUrl:'Logo',imageUrls:'Imágenes',additionalInfo:'Datos adicionales',campaignNotes:'Notas de campaña'};
function methodLabel(value:unknown){const v=String(value||'manual');return v==='api'?'API · Local Lab':v==='network'?'Red / agregador · Local Lab':'Manual · Local Lab';}
function originLabel(value:unknown){return text(value,'Manual / Local Lab');}
function profileValue(value:unknown){if(Array.isArray(value))return value.join(', ');if(value&&typeof value==='object')return Object.entries(value as Row).map(([k,v])=>`${k}: ${String(v)}`).join(' · ');return text(value,'Pendiente');}

const dayOrder:[string,string][]=[['monday','Lunes'],['tuesday','Martes'],['wednesday','Miércoles'],['thursday','Jueves'],['friday','Viernes'],['saturday','Sábado'],['sunday','Domingo']];
const evidenceTypeLabels:Record<string,string>={screenshot:'Captura',listing:'Ficha',email:'Email',document:'Documento',other:'Evidencia'};
function isLiveStatus(value:unknown){return isLivePublicationStatus(value);}
function qaStatus(item:Row){return citationQaPresentation(item.status,rec(rec(item.qa).checks));}
function reportCsvCell(value:unknown){const raw=String(value??'').replace(/\r?\n/g,' ');return `"${raw.replace(/"/g,'""')}"`;}
function mediaName(url:string,index:number){try{const parsed=new URL(url);return parsed.pathname.split('/').filter(Boolean).pop()||`Imagen ${index+1}`;}catch{return `Imagen ${index+1}`;}}

export default function UtilidadesCitationBuilderV24({locationId,locationName,onAction}:Props){
  const [overview,setOverview]=useState<Row>({});
  const [detail,setDetail]=useState<Row|null>(null);
  const [tab,setTab]=useState<Tab>('resumen');
  const [loading,setLoading]=useState(true); const [error,setError]=useState<string|null>(null); const [success,setSuccess]=useState<string|null>(null);
  const [modal,setModal]=useState<string|null>(null); const [draft,setDraft]=useState<Row>({}); const [selected,setSelected]=useState<Row|null>(null);
  const [preview,setPreview]=useState<Row|null>(null);
  const [campaignQuery,setCampaignQuery]=useState(''); const [campaignStatusFilter,setCampaignStatusFilter]=useState('all'); const [campaignOriginFilter,setCampaignOriginFilter]=useState('all'); const [campaignSort,setCampaignSort]=useState('updated');
  const campaign=rec(detail?.campaign); const campaignId=n(campaign.id);

  async function loadOverview(){ setLoading(true); try{ setOverview(await utilidadesV15Api.citationBuilder(locationId)); setError(null); }catch(e){setError(e instanceof Error?e.message:'No se pudo cargar Citation Builder.');}finally{setLoading(false);} }
  async function openCampaign(id:number){ setLoading(true); try{ const current=new URL(window.location.href); const preserveDeepLink=current.searchParams.get('builderCampaign')===String(id); const data=await utilidadesV15Api.citationBuilderCampaign(locationId,id); setDetail(data); const requestedTab=current.searchParams.get('builderTab') as Tab|null; const validTab=Boolean(requestedTab&&tabs.some(([key])=>key===requestedTab)); setTab(preserveDeepLink&&validTab?requestedTab as Tab:'resumen'); const evidenceId=preserveDeepLink?current.searchParams.get('evidenceId'):null; if(evidenceId){const found=rows(data.evidence).find(row=>String(row.id)===evidenceId);if(found){setPreview({...found,previewKind:'evidence'});setModal('resource-preview');setTab('evidencias');}} current.searchParams.set('builderCampaign',String(id)); if(!preserveDeepLink){current.searchParams.delete('builderTab');current.searchParams.delete('evidenceId');} window.history.replaceState({},'',current);setError(null);}catch(e){setError(e instanceof Error?e.message:'No se pudo abrir la campaña.');}finally{setLoading(false);} }
  function closeCampaign(){setDetail(null);setTab('resumen');setPreview(null);setModal(null);const url=new URL(window.location.href);['builderCampaign','builderTab','evidenceId'].forEach(key=>url.searchParams.delete(key));window.history.replaceState({},'',url);} 
  function selectWorkspaceTab(next:Tab){setTab(next);const url=new URL(window.location.href);url.searchParams.set('builderTab',next);if(next!=='evidencias')url.searchParams.delete('evidenceId');window.history.replaceState({},'',url);}
  function closeResourcePreview(){setPreview(null);setModal(null);const url=new URL(window.location.href);url.searchParams.delete('evidenceId');window.history.replaceState({},'',url);}
  function openEvidencePreview(evidenceRow:Row){setPreview({...evidenceRow,previewKind:evidenceRow.previewKind||'evidence'});setTab('evidencias');setModal('resource-preview');const url=new URL(window.location.href);url.searchParams.set('builderCampaign',String(campaignId));url.searchParams.set('builderTab','evidencias');url.searchParams.set('evidenceId',String(evidenceRow.id));window.history.replaceState({},'',url);}
  function openItemReference(item:Row,kind:'listing'|'submission'){const resourceUrl=kind==='listing'?item.listingUrl:(item.evidenceUrl||item.listingUrl);setPreview({...item,previewKind:kind,resourceUrl});setModal('resource-preview');}
  async function reloadDetail(){ if(!campaignId)return; try{setDetail(await utilidadesV15Api.citationBuilderCampaign(locationId,campaignId)); setOverview(await utilidadesV15Api.citationBuilder(locationId));}catch(e){setError(e instanceof Error?e.message:'No se pudo actualizar la campaña.');} }
  useEffect(()=>{void loadOverview();const requested=Number(new URL(window.location.href).searchParams.get('builderCampaign'));if(Number.isInteger(requested)&&requested>0)void openCampaign(requested);},[locationId]);

  const metrics=rec(detail?.metrics); const readiness=rec(detail?.readiness); const items=rows(detail?.items); const actions=rows(detail?.actionsRequired); const evidence=rows(detail?.evidence); const duplicates=rows(detail?.duplicates); const timeline=rows(detail?.timeline); const tracker=rows(detail?.trackerOpportunities); const trackerDuplicates=rows(detail?.trackerDuplicates); const profile=rec(detail?.profile); const pipeline=rows(detail?.pipeline); const credentials=rows(detail?.credentials);
  const missing=rows(overview.campaigns).length===0;

  async function createCampaign(e:FormEvent){e.preventDefault();setLoading(true);try{const result=await utilidadesV15Api.citationBuilderCreateCampaign(locationId,{name:draft.name||`Campaña Citation Builder · ${locationName}`,source:'manual'});setModal(null);setDraft({});setSuccess('Campaña creada.');await loadOverview();const id=n(rec(result.campaign).id);if(id)await openCampaign(id);}catch(c){setError(c instanceof Error?c.message:'No se pudo crear la campaña.');}finally{setLoading(false);}}
  async function importTracker(){if(!campaignId)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderImportTracker(locationId,campaignId));setSuccess('Oportunidades de Citation Tracker importadas.');await loadOverview();}catch(c){setError(c instanceof Error?c.message:'No se pudo importar Citation Tracker.');}finally{setLoading(false);}}
  async function runLab(){setLoading(true);try{const result=await utilidadesV15Api.citationBuilderRunLab(locationId);setDetail(result);setSuccess('Ejecución Local Lab V24.3 completada.');await loadOverview();}catch(c){setError(c instanceof Error?c.message:'No se pudo ejecutar Local Lab.');}finally{setLoading(false);}}
  async function saveProfile(e:FormEvent){e.preventDefault();if(!campaignId)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderProfile(locationId,campaignId,draft));setModal(null);setSuccess('Dataset de envíos actualizado.');}catch(c){setError(c instanceof Error?c.message:'No se pudo actualizar el dataset.');}finally{setLoading(false);}}
  async function addDirectory(e:FormEvent){e.preventDefault();if(!campaignId)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderAddDirectory(locationId,campaignId,draft));setModal(null);setSuccess('Directorio añadido a la campaña.');}catch(c){setError(c instanceof Error?c.message:'No se pudo añadir el directorio.');}finally{setLoading(false);}}
  async function updateItem(status:string){if(!campaignId||!selected)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderItemStatus(locationId,campaignId,n(selected.id),{status,note:draft.note||'',listingUrl:draft.listingUrl||selected.listingUrl||undefined}));setModal(null);setSuccess(`Envío actualizado a ${statusLabels[status]||status}.`);}catch(c){setError(c instanceof Error?c.message:'No se pudo actualizar el envío.');}finally{setLoading(false);}}
  async function addEvidence(e:FormEvent){e.preventDefault();if(!campaignId||!selected)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderEvidence(locationId,campaignId,n(selected.id),draft));setModal(null);setSuccess('Evidencia registrada.');}catch(c){setError(c instanceof Error?c.message:'No se pudo registrar evidencia.');}finally{setLoading(false);}}
  async function addRequired(e:FormEvent){e.preventDefault();if(!campaignId||!selected)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderAction(locationId,campaignId,n(selected.id),draft));setModal(null);setSuccess('Acción requerida añadida.');}catch(c){setError(c instanceof Error?c.message:'No se pudo crear la acción requerida.');}finally{setLoading(false);}}
  async function resolveRequired(action:Row){if(!campaignId)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderResolveAction(locationId,campaignId,n(action.itemId),String(action.id)));setSuccess('Acción requerida resuelta.');}catch(c){setError(c instanceof Error?c.message:'No se pudo resolver la acción.');}finally{setLoading(false);}}
  async function runQa(e:FormEvent){e.preventDefault();if(!campaignId||!selected)return;const checks={name:Boolean(draft.qaName),address:Boolean(draft.qaAddress),phone:Boolean(draft.qaPhone),website:Boolean(draft.qaWebsite),category:Boolean(draft.qaCategory)};setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderQa(locationId,campaignId,n(selected.id),{checks,note:draft.note||''}));setModal(null);setSuccess(Object.values(checks).every(Boolean)?'QA aprobado; el estado de publicación se conserva de forma independiente.':'QA detectó diferencias y creó una acción requerida.');}catch(c){setError(c instanceof Error?c.message:'No se pudo ejecutar QA del envío.');}finally{setLoading(false);}}
  async function addDuplicate(e:FormEvent){e.preventDefault();if(!campaignId)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderAddDuplicate(locationId,campaignId,draft));setModal(null);setSuccess('Tarea de duplicado registrada.');}catch(c){setError(c instanceof Error?c.message:'No se pudo registrar duplicado.');}finally{setLoading(false);}}
  async function duplicateStatus(dup:Row,status:string){if(!campaignId)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderUpdateDuplicate(locationId,campaignId,String(dup.id),{directoryName:dup.directoryName,status,note:dup.note||''}));setSuccess('Estado del duplicado actualizado.');}catch(c){setError(c instanceof Error?c.message:'No se pudo actualizar duplicado.');}finally{setLoading(false);}}
  async function addCredential(e:FormEvent){e.preventDefault();if(!campaignId)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderCredential(locationId,campaignId,draft));setModal(null);setSuccess('Referencia de credencial registrada sin exponer contraseña.');}catch(c){setError(c instanceof Error?c.message:'No se pudo registrar credencial.');}finally{setLoading(false);}}
  async function campaignStatus(status:string){if(!campaignId)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderCampaignStatus(locationId,campaignId,{status}));setSuccess(`Campaña ${statusLabels[status]||status}.`);await loadOverview();}catch(c){setError(c instanceof Error?c.message:'No se pudo cambiar el estado.');}finally{setLoading(false);}}
  async function updateSpecificItem(item:Row,status:string,note=''){if(!campaignId)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderItemStatus(locationId,campaignId,n(item.id),{status,note,listingUrl:item.listingUrl||undefined}));setSuccess(`Envío actualizado a ${statusLabels[status]||status}.`);}catch(c){setError(c instanceof Error?c.message:'No se pudo actualizar el envío.');}finally{setLoading(false);}}
  async function bulkUpdateItems(ids:number[],status:string){if(!campaignId||!ids.length)return;setLoading(true);try{for(const id of ids){await utilidadesV15Api.citationBuilderItemStatus(locationId,campaignId,id,{status,note:'Actualización masiva desde Campaign Workspace'});}await reloadDetail();setSuccess(`${ids.length} envío(s) actualizados.`);}catch(c){setError(c instanceof Error?c.message:'No se pudo completar la actualización masiva.');}finally{setLoading(false);}}
  async function importTrackerDuplicates(){if(!campaignId)return;setLoading(true);try{setDetail(await utilidadesV15Api.citationBuilderImportTrackerDuplicates(locationId,campaignId));setSuccess('Duplicados de Citation Tracker importados al workflow.');}catch(c){setError(c instanceof Error?c.message:'No se pudieron importar duplicados del Tracker.');}finally{setLoading(false);}}

  function downloadCampaignCsv(){if(!detail||!campaignId)return;const headers=['Directorio','Método','Estado','QA','NAP','Responsable','Enviado','Próxima revisión','Referencia'];const data=items.filter(i=>String(i.status)!=='replaced').map(i=>{const qa=qaStatus(i);return[i.directoryName,methodLabel(i.method),statusLabels[String(i.status)]||i.status,qa.label,qa.score,i.owner,formatDate(i.submittedAt),i.nextReviewAt?formatDate(i.nextReviewAt):'',isLiveStatus(i.status)?i.listingUrl:(i.evidenceUrl||i.listingUrl||'')];});const csv=[headers,...data].map(row=>row.map(reportCsvCell).join(',')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download=`citation-builder-${campaignId}.csv`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(href);setSuccess('CSV de campaña generado.');}
  function printCampaignReport(){if(!detail||!campaignId)return;const w=window.open('','_blank','noopener,noreferrer,width=1100,height=800');if(!w){setError('El navegador bloqueó la ventana del reporte. Habilita ventanas emergentes para imprimir o guardar PDF.');return;}const doc=w.document;doc.title=`Citation Builder · ${text(campaign.displayName||campaign.name)}`;const style=doc.createElement('style');style.textContent='body{font-family:Arial,sans-serif;color:#172536;padding:32px}h1{margin:0 0 6px}small{color:#667085}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:22px 0}.kpi{border:1px solid #ddd;border-radius:10px;padding:12px}.kpi b{display:block;font-size:24px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border-bottom:1px solid #e5e7eb;text-align:left;padding:8px;font-size:12px}th{background:#f5f6f8}.footer{margin-top:24px;font-size:11px;color:#667085}@media print{button{display:none}}';doc.head.appendChild(style);const h1=doc.createElement('h1');h1.textContent=text(campaign.displayName||campaign.name);doc.body.appendChild(h1);const subtitle=doc.createElement('small');subtitle.textContent=`SEOLOCAL Citation Builder V24.3 · Local Lab · ${n(metrics.total)} envíos · ${n(metrics.live)} activas`;doc.body.appendChild(subtitle);const kpis=doc.createElement('div');kpis.className='kpis';[['Avance operativo',`${n(metrics.operationalProgress)}%`],['Cobertura activa',`${n(metrics.activeCoverage)}%`],['Preparación de datos',`${n(readiness.percent)}%`],['QA pendiente',String(n(metrics.qaPending))]].forEach(([label,value])=>{const box=doc.createElement('div');box.className='kpi';const span=doc.createElement('span');span.textContent=label;const b=doc.createElement('b');b.textContent=value;box.append(span,b);kpis.appendChild(box)});doc.body.appendChild(kpis);const table=doc.createElement('table');const thead=doc.createElement('thead');const hr=doc.createElement('tr');['Directorio','Estado','QA','Método','Responsable','Referencia'].forEach(label=>{const th=doc.createElement('th');th.textContent=label;hr.appendChild(th)});thead.appendChild(hr);table.appendChild(thead);const tbody=doc.createElement('tbody');items.filter(i=>String(i.status)!=='replaced').forEach(i=>{const qa=qaStatus(i);const tr=doc.createElement('tr');[text(i.directoryName),statusLabels[String(i.status)]||text(i.status),`${qa.label} · ${qa.score}`,methodLabel(i.method),text(i.owner),text(isLiveStatus(i.status)?i.listingUrl:(i.evidenceUrl||i.listingUrl),'—')].forEach(value=>{const td=doc.createElement('td');td.textContent=value;tr.appendChild(td)});tbody.appendChild(tr)});table.appendChild(tbody);doc.body.appendChild(table);const footer=doc.createElement('p');footer.className='footer';footer.textContent='Reporte Local Lab para validación funcional. No representa confirmación de ejecución en directorios externos.';doc.body.appendChild(footer);w.focus();setTimeout(()=>w.print(),250);}
  async function copyInternalReportLink(){if(!campaignId)return;const url=new URL(window.location.href);url.searchParams.set('builderCampaign',String(campaignId));try{await navigator.clipboard.writeText(url.toString());setSuccess('Enlace interno de la campaña copiado. Requiere una sesión autorizada de SEOLOCAL.');}catch{setError('No se pudo copiar el enlace interno.');}}

  const filteredCampaigns=rows(overview.campaigns).filter(c=>{
    const q=campaignQuery.trim().toLowerCase(); const matchesQuery=!q||text(c.displayName||c.name).toLowerCase().includes(q)||originLabel(c.originLabel).toLowerCase().includes(q);
    const matchesStatus=campaignStatusFilter==='all'||String(c.status)===campaignStatusFilter;
    const matchesOrigin=campaignOriginFilter==='all'||originLabel(c.originLabel)===campaignOriginFilter;
    return matchesQuery&&matchesStatus&&matchesOrigin;
  }).sort((a,b)=>campaignSort==='progress'?n(b.operationalProgress)-n(a.operationalProgress):campaignSort==='name'?text(a.displayName||a.name).localeCompare(text(b.displayName||b.name)):Date.parse(String(b.updatedAt||0))-Date.parse(String(a.updatedAt||0)));

  return <div className="cb24-root">
    <ErrorBox message={error} onRetry={detail?reloadDetail:loadOverview}/><SuccessBox message={success}/>
    {!detail ? <>
      <section className="cb24-hero"><div><div className="cb24-badges"><span>LOCAL LAB V24.3</span><span className="ok">Persistencia activa</span></div><h2>Citation Builder</h2><p>Gestor de campañas operativo de altas, actualización, verificación, QA, evidencias y resolución de duplicados para {locationName}.</p><small>Tracker descubre → Builder ejecuta → Ficha activa → QA valida → Evidencia demuestra → Tracker confirma.</small></div><div className="cb24-hero-actions"><button className="util-btn" onClick={()=>void runLab()}><Sparkles size={15}/>Probar Local Lab</button><button className="util-btn primary" onClick={()=>{setDraft({name:`Campaña Citation Builder · ${locationName}`});setModal('create')}}><Plus size={15}/>Nueva campaña</button></div></section>
      <div className="cb24-kpis"><BuilderKpi label="Campañas activas" value={n(rec(overview.metrics).activeCampaigns)} icon={<Rocket/>}/><BuilderKpi label="Envíos" value={n(rec(overview.metrics).submissions)} icon={<Send/>}/><BuilderKpi label="Activas" value={n(rec(overview.metrics).live)} icon={<BadgeCheck/>}/><BuilderKpi label="Acción requerida" value={n(rec(overview.metrics).actionRequired)} icon={<AlertTriangle/>}/><BuilderKpi label="En verificación" value={n(rec(overview.metrics).verification)} icon={<Send/>}/><BuilderKpi label="QA pendiente" value={n(rec(overview.metrics).qaPending)} icon={<ClipboardCheck/>}/><BuilderKpi label="Incidencias" value={n(rec(overview.metrics).issues)} icon={<Wrench/>}/><BuilderKpi label="Oportunidades Tracker" value={n(rec(overview.metrics).trackerOpportunities)} icon={<Search/>}/></div>
      <section className="cb24-panel"><div className="cb24-panel-head"><div><span>GESTOR DE CAMPAÑAS</span><h3>Campañas de citaciones</h3><p>Avance, cobertura activa y próxima acción de cada campaña.</p></div></div><div className="cb24-manager-tools"><label><Search size={15}/><input value={campaignQuery} onChange={e=>setCampaignQuery(e.target.value)} placeholder="Buscar campaña..."/></label><select value={campaignStatusFilter} onChange={e=>setCampaignStatusFilter(e.target.value)}><option value="all">Todos los estados</option><option value="active">Activas</option><option value="draft">Preparación</option><option value="paused">Pausadas</option><option value="completed">Completadas</option></select><select value={campaignOriginFilter} onChange={e=>setCampaignOriginFilter(e.target.value)}><option value="all">Todos los orígenes</option><option>Citation Tracker</option><option>Local Lab</option><option>Manual / Local Lab</option></select><select value={campaignSort} onChange={e=>setCampaignSort(e.target.value)}><option value="updated">Más recientes</option><option value="progress">Mayor avance</option><option value="name">Nombre A-Z</option></select></div>{missing?<div className="cb24-empty"><Boxes size={30}/><h3>No hay campañas</h3><p>Crea una campaña o ejecuta el Local Lab para comenzar.</p></div>:<div className="cb24-campaign-grid">{filteredCampaigns.map(c=><button key={n(c.id)} className="cb24-campaign-card" onClick={()=>void openCampaign(n(c.id))}><div className="cb24-card-top"><span className={`cb24-status ${statusClass(c.status)}`}>{statusLabels[String(c.status)]||text(c.status)}</span><span className="cb24-origin">Origen: {originLabel(c.originLabel)}</span></div><h3>{text(c.displayName||c.name)}</h3><div className="cb24-card-progress-head"><span>Avance operativo</span><strong>{n(c.operationalProgress||c.progress)}%</strong></div><div className="cb24-progress"><span style={{width:pct(c.operationalProgress||c.progress)}}/></div><div className="cb24-card-metrics"><span><b>{n(c.directoryCount)}</b> envíos</span><span><b>{n(c.liveCount)}</b> activas</span><span><b>{n(c.activeCoverage)}%</b> cobertura activa</span><span><b>{n(c.readiness)}%</b> preparación de datos</span></div><div className="cb24-next-action"><b>Próxima acción</b><span>{text(c.nextAction)}</span></div><small>Actualizada {formatDate(c.updatedAt)}</small></button>)}</div>}</section>
    </> : <>
      <section className="cb24-hero cb24-detail-hero"><div><button className="cb24-back" onClick={closeCampaign}><ArrowLeft size={15}/>Campañas</button><div className="cb24-badges"><span>LOCAL LAB V24.3</span><span className="ok">Campaña #{campaignId}</span></div><h2>{text(campaign.displayName||campaign.name)}</h2><p>Pipeline operacional completo con evidencia y QA.</p><small>{n(metrics.total)} envíos · {n(metrics.live)} activas · {n(metrics.actionRequired)} requieren acción · Origen: {originLabel(campaign.originLabel)}</small></div><div className="cb24-hero-actions"><span className={`cb24-status ${statusClass(campaign.status)}`}>{statusLabels[String(campaign.status)]||text(campaign.status)}</span>{String(campaign.status)==='draft'?<button className="util-btn primary" onClick={()=>void campaignStatus('active')}><Rocket size={15}/>Activar campaña</button>:null}<button className="util-btn" onClick={()=>setModal('report')}><FileCheck2 size={15}/>Reporte</button><button className="util-btn" onClick={()=>void reloadDetail()}><RefreshCw size={15}/>Actualizar</button></div></section>
      <div className="cb24-kpis"><BuilderKpi label="Preparación" value={n(metrics.preparation)} icon={<Wrench/>}/><BuilderKpi label="Enviadas / Verificación" value={n(metrics.submitted)} icon={<Send/>}/><BuilderKpi label="Acción requerida" value={n(metrics.actionRequired)} icon={<AlertTriangle/>}/><BuilderKpi label="Activas" value={n(metrics.live)} icon={<BadgeCheck/>}/><BuilderKpi label="QA pendiente" value={n(metrics.qaPending)} icon={<ClipboardCheck/>}/><BuilderKpi label="Incidencias" value={n(metrics.issues)} icon={<Wrench/>}/><BuilderKpi label="Avance operativo" value={`${n(metrics.operationalProgress||metrics.progress)}%`} icon={<Rocket/>}/><BuilderKpi label="Preparación de datos" value={`${n(readiness.percent)}%`} icon={<ListChecks/>}/></div>
      <section className="cb24-panel cb24-workspace"><nav className="cb24-tabs">{tabs.map(([key,label])=><button key={key} className={tab===key?'active':''} onClick={()=>selectWorkspaceTab(key)}>{label}{key==='acciones'&&actions.length?<em>{actions.length}</em>:null}{key==='evidencias'&&evidence.length?<em>{evidence.length}</em>:null}</button>)}</nav>
        {tab==='resumen'?<Summary pipeline={pipeline} metrics={metrics} readiness={readiness} actions={actions} timeline={timeline} cost={rec(detail.costEstimate)} onImport={importTracker} trackerCount={tracker.length} onAction={onAction}/>:null}
        {tab==='datos'?<BusinessData profile={profile} readiness={readiness} onEdit={()=>{setDraft({...profile});setModal('profile')}}/>:null}
        {tab==='directorios'?<Directories tracker={tracker} items={items} onImport={importTracker} onAdd={()=>{setDraft({method:'manual',pricing:'free',authority:60,priority:60});setModal('directory')}} onRemove={(item)=>void updateSpecificItem(item,'replaced','Quitado de la campaña desde Selección de directorios')}/>:null}
        {tab==='submissions'?<Submissions items={items.filter(i=>!['replaced'].includes(String(i.status)))} onOpen={(item)=>{setSelected(item);setDraft({listingUrl:item.listingUrl||'',note:''});setModal('item')}} onReference={openItemReference} onBulk={bulkUpdateItems}/>:null}
        {tab==='acciones'?<RequiredActions actions={actions} onResolve={resolveRequired} onAction={onAction}/>:null}
        {tab==='evidencias'?<EvidenceCenter evidence={evidence} onPreview={openEvidencePreview} onQa={(e)=>{const item=items.find(row=>n(row.id)===n(e.itemId));if(item){setSelected(item);setDraft({qaName:true,qaAddress:true,qaPhone:true,qaWebsite:true,qaCategory:true});setModal('qa');}}}/>:null}
        {tab==='duplicados'?<Duplicates items={duplicates} trackerDuplicates={trackerDuplicates} onImport={importTrackerDuplicates} onAdd={()=>{setDraft({status:'detected'});setModal('duplicate')}} onStatus={duplicateStatus}/>:null}
        {tab==='historial'?<HistoryTab timeline={timeline} credentials={credentials} onCredential={()=>{setDraft({});setModal('credential')}}/>:null}
      </section>
    </>}
    {modal==='create'?<Modal title="Nueva campaña Citation Builder" onClose={()=>setModal(null)} footer={<button className="util-btn primary" form="cb24-create">Crear campaña</button>}><form id="cb24-create" onSubmit={createCampaign} className="cb24-form"><label>Nombre<input required value={String(draft.name||'')} onChange={e=>setDraft({...draft,name:e.target.value})}/></label><p className="cb24-help">La campaña utilizará el NAP de la ubicación y podrá importar oportunidades desde Citation Tracker.</p></form></Modal>:null}
    {modal==='profile'?<ProfileModal draft={draft} setDraft={setDraft} onSubmit={saveProfile} onClose={()=>setModal(null)}/>:null}
    {modal==='directory'?<DirectoryModal draft={draft} setDraft={setDraft} onSubmit={addDirectory} onClose={()=>setModal(null)}/>:null}
    {modal==='item'&&selected?<ItemModal item={selected} draft={draft} setDraft={setDraft} onClose={()=>setModal(null)} onStatus={updateItem} onEvidence={()=>{setDraft({title:`Evidencia · ${text(selected.directoryName)}`,type:'screenshot',url:selected.listingUrl||''});setModal('evidence')}} onRequired={()=>{setDraft({title:'Verificación requerida',instructions:''});setModal('required')}} onQa={()=>{setDraft({qaName:true,qaAddress:true,qaPhone:true,qaWebsite:true,qaCategory:true});setModal('qa')}}/>:null}
    {modal==='evidence'&&selected?<EvidenceModal draft={draft} setDraft={setDraft} onSubmit={addEvidence} onClose={()=>setModal('item')}/>:null}
    {modal==='required'&&selected?<RequiredModal draft={draft} setDraft={setDraft} onSubmit={addRequired} onClose={()=>setModal('item')}/>:null}
    {modal==='qa'&&selected?<QaModal draft={draft} setDraft={setDraft} onSubmit={runQa} onClose={()=>setModal('item')}/>:null}
    {modal==='duplicate'?<DuplicateModal draft={draft} setDraft={setDraft} onSubmit={addDuplicate} onClose={()=>setModal(null)}/>:null}
    {modal==='report'?<ReportModal onClose={()=>setModal(null)} onCsv={downloadCampaignCsv} onPrint={printCampaignReport} onCopy={copyInternalReportLink}/>:null}
    {modal==='credential'?<CredentialModal draft={draft} setDraft={setDraft} onSubmit={addCredential} onClose={()=>setModal(null)}/>:null}
    {modal==='resource-preview'&&preview?<ResourcePreviewModal resource={preview} item={items.find(row=>n(row.id)===n(preview.itemId||preview.id))||null} onClose={closeResourcePreview} onQa={(item)=>{setSelected(item);setDraft({qaName:true,qaAddress:true,qaPhone:true,qaWebsite:true,qaCategory:true});setModal('qa')}}/>:null}
    <Loading show={loading}/>
  </div>;
}

function BuilderKpi({label,value,icon}:{label:string;value:unknown;icon:React.ReactNode}){return <div className="cb24-kpi"><span>{icon}{label}</span><strong>{String(value)}</strong></div>}
function Summary({pipeline,metrics,readiness,actions,timeline,cost,onImport,trackerCount,onAction}:{pipeline:Row[];metrics:Row;readiness:Row;actions:Row[];timeline:Row[];cost:Row;onImport:()=>void;trackerCount:number;onAction:(t:string,d:string)=>void}){const missing=[...rows(readiness.missing),...rows(readiness.dynamicMissing)].map(v=>missingLabels[String(v)]||String(v));return <div className="cb24-summary"><div className="cb24-pipeline"><div className="cb24-section-title"><span>PIPELINE DE PUBLICACIÓN</span><h3>Preparación → Envío → Verificación → Activa</h3></div><div className="cb24-phase-grid">{pipeline.map(p=><div className="cb24-phase" key={String(p.code)}>{phaseIcons[String(p.code)]}<span>{text(p.label)}</span><strong>{n(p.count)}</strong></div>)}</div><div className="cb24-qa-parallel"><ClipboardCheck size={18}/><div><small>QA PARALELO</small><b>{n(metrics.qaApproved)} aprobadas · {n(metrics.qaPending)} pendientes · {n(metrics.qaIssues)} con incidencia</b><span>El QA valida la calidad sin reemplazar el estado real de publicación.</span></div></div></div><div className="cb24-grid2"><div className="cb24-card"><div className="cb24-section-title"><span>PREPARACIÓN DE DATOS</span><h3>{n(readiness.percent)}% listo para enviar</h3></div><div className="cb24-progress lg"><span style={{width:pct(readiness.percent)}}/></div><p>{n(readiness.complete)}/{n(readiness.total)} bloques base completos.</p>{missing.length?<small>Falta completar: {missing.join(', ')}</small>:<span className="cb24-good"><CheckCircle2 size={15}/>Dataset y requisitos completos</span>}</div><div className="cb24-card"><div className="cb24-section-title"><span>TRACKER → BUILDER</span><h3>{trackerCount} oportunidades disponibles</h3></div><p>Importa los directorios priorizados por Citation Tracker sin volver a capturar información.</p><button className="util-btn primary" onClick={()=>void onImport()}><Upload size={15}/>Importar oportunidades</button></div></div><div className="cb24-grid2"><div className="cb24-card"><div className="cb24-section-title"><span>ACCIONES REQUERIDAS</span><h3>{actions.length} pendientes de colaboración</h3></div>{actions.slice(0,3).map(a=><div className="cb24-mini-row" key={String(a.id)}><AlertTriangle size={15}/><div><b>{text(a.directoryName)}</b><small>{text(a.title)}</small></div><button onClick={()=>onAction(`Citation Builder · ${text(a.directoryName)}`,text(a.instructions))}>Crear acción</button></div>)}{!actions.length?<p>Sin bloqueos operativos.</p>:null}</div><div className="cb24-card"><div className="cb24-section-title"><span>COSTE ESTIMADO</span><h3>{n(cost.credits)} créditos demo</h3></div><p>{text(cost.note,'Estimación interna Local Lab · Sin valor comercial.')}</p></div></div><div className="cb24-card"><div className="cb24-section-title"><span>ACTIVIDAD RECIENTE</span><h3>Línea de tiempo operativa</h3></div>{timeline.slice(0,7).map(t=><div className="cb24-timeline-row" key={String(t.id)}><span/><div><b>{text(t.title)}</b><p>{text(t.detail)}</p></div><time>{formatDate(t.at)}</time></div>)}</div></div>}
function BusinessData({profile,readiness,onEdit}:{profile:Row;readiness:Row;onEdit:()=>void}){const fields=[['Nombre',profile.name],['Dirección',profile.address],['Teléfono',profile.phone],['Código postal',profile.postcode],['Sitio web',profile.website],['Email',profile.email],['Contacto',profile.contactName],['Categoría principal',profile.primaryCategory],['Categorías secundarias',profile.secondaryCategories],['Servicios',profile.services],['Descripción',profile.description],['Métodos de pago',profile.paymentMethods],['Redes sociales',profile.socialProfiles],['Datos adicionales',profile.additionalInfo],['Notas de campaña',profile.campaignNotes]];const missing=[...rows(readiness.missing),...rows(readiness.dynamicMissing)].map(v=>missingLabels[String(v)]||String(v));const hours=rec(profile.hours);const images=rows(profile.imageUrls).map(String);return <div><div className="cb24-panel-head inline"><div><span>DATOS PARA ENVÍOS</span><h3>Dataset maestro de la campaña</h3><p>{n(readiness.complete)}/{n(readiness.total)} bloques base completos · {n(readiness.percent)}% preparación de datos.</p>{missing.length?<small>Falta completar: {missing.join(', ')}</small>:null}</div><button className="util-btn primary" onClick={onEdit}><UserRoundCog size={15}/>Editar datos</button></div><div className="cb24-profile-grid">{fields.map(([k,v])=><div key={String(k)}><small>{String(k)}</small><strong>{profileValue(v)}</strong></div>)}<div className="cb24-hours-card"><small>Horarios</small><div className="cb24-hours-list">{dayOrder.map(([key,label])=><span key={key}><b>{label}</b><em>{text(hours[key],'Sin horario')}</em></span>)}</div></div><div className="cb24-media-card"><small>Logo</small><div className="cb24-media-item"><FileImage size={18}/><div><b>{profile.logoUrl?'Logo configurado':'Pendiente'}</b><span>{profile.logoUrl?mediaName(String(profile.logoUrl),0):'Sin archivo'}</span></div></div></div><div className="cb24-media-card wide"><small>Imágenes</small><div className="cb24-media-list">{images.map((url,index)=><div className="cb24-media-item" key={url}><FileImage size={18}/><div><b>{mediaName(url,index)}</b><span>Imagen #{index+1}</span></div></div>)}{!images.length?<span>Pendiente</span>:null}</div></div></div></div>}
function Directories({tracker,items,onImport,onAdd,onRemove}:{tracker:Row[];items:Row[];onImport:()=>void;onAdd:()=>void;onRemove:(i:Row)=>void}){const byName=new Map(items.filter(i=>!['replaced','rejected'].includes(String(i.status))).map(i=>[String(i.directoryName).toLowerCase(),i]));return <div><div className="cb24-panel-head inline"><div><span>SELECCIÓN DE DIRECTORIOS</span><h3>Oportunidades, requisitos y viabilidad</h3></div><div><button className="util-btn" onClick={()=>void onImport()}><Upload size={15}/>Importar Tracker</button><button className="util-btn primary" onClick={onAdd}><Plus size={15}/>Añadir directorio</button></div></div><div className="cb24-directory-grid">{tracker.map(d=>{const item=byName.get(String(d.directoryName).toLowerCase());const requirements=rows(item?.requirements||d.requirements);return <div className={`cb24-directory-card ${item?'selected':''}`} key={String(d.directoryName)}><div><b>{text(d.directoryName)}</b><small>{text(d.category)} · {text(d.pricing)==='paid'?'Pago':'Gratis'} · {n(d.competitorCount)}/5 competidores</small><div className="cb24-requirements">{requirements.length?requirements.map(r=><span key={String(r)}>{String(r)}</span>):<span>Sin requisitos adicionales</span>}<span>{item?methodLabel(item.method):'Método por definir'}</span></div></div><div className="cb24-score"><span>Autoridad {n(d.authority)}</span><strong>Prioridad {n(d.priority)}</strong></div>{item?<div className="cb24-directory-actions"><span className="cb24-good"><CheckCircle2 size={14}/>En campaña</span><button className="cb24-link-btn" onClick={()=>onRemove(item)}>Quitar</button></div>:<span className="cb24-status neutral">Disponible</span>}</div>})}</div></div>}
function ResourceAction({url,label,onInternal}:{url:unknown;label:string;onInternal:()=>void}){const value=String(url||'');if(!value)return null;if(isLocalLabResourceUrl(value))return <button type="button" className="cb24-resource-link" onClick={onInternal}>{label} <ExternalLink size={12}/></button>;return <a className="cb24-live-url" href={value} target="_blank" rel="noreferrer">{label} <ExternalLink size={12}/></a>}
function Submissions({items,onOpen,onReference,onBulk}:{items:Row[];onOpen:(i:Row)=>void;onReference:(i:Row,k:'listing'|'submission')=>void;onBulk:(ids:number[],status:string)=>void}){const [query,setQuery]=useState('');const [status,setStatus]=useState('all');const [method,setMethod]=useState('all');const [selectedIds,setSelectedIds]=useState<number[]>([]);const visible=items.filter(i=>{const q=query.trim().toLowerCase();return(!q||text(i.directoryName).toLowerCase().includes(q))&&(status==='all'||String(i.status)===status)&&(method==='all'||String(i.method)===method)});const toggle=(id:number)=>setSelectedIds(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id]);return <div><div className="cb24-submission-tools"><label><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar directorio..."/></label><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Todos los estados</option><option value="preparing">Preparar</option><option value="submitted">Enviada</option><option value="verification">Verificación</option><option value="live">Activa</option></select><select value={method} onChange={e=>setMethod(e.target.value)}><option value="all">Todos los métodos</option><option value="manual">Manual</option><option value="api">API</option><option value="network">Red / agregador</option></select>{selectedIds.length?<><span className="cb24-selection-count">{selectedIds.length} seleccionados</span><button className="util-btn" onClick={()=>void onBulk(selectedIds,'submitted')}>Marcar enviadas</button><button className="util-btn" onClick={()=>void onBulk(selectedIds,'verification')}>A verificación</button></>:null}</div><div className="cb24-table-wrap"><table><thead><tr><th><input type="checkbox" checked={visible.length>0&&visible.every(i=>selectedIds.includes(n(i.id)))} onChange={e=>setSelectedIds(e.target.checked?visible.map(i=>n(i.id)):[])}/></th><th>Directorio</th><th>Método</th><th>Estado</th><th>QA</th><th>Responsable</th><th>Enviado</th><th>Próxima revisión</th><th>Referencia</th><th>Evidencia</th><th/></tr></thead><tbody>{visible.map(i=>{const qa=qaStatus(i);const ref=i.listingUrl||i.evidenceUrl;const live=isLiveStatus(i.status);return <tr key={n(i.id)}><td><input type="checkbox" checked={selectedIds.includes(n(i.id))} onChange={()=>toggle(n(i.id))}/></td><td><b>{text(i.directoryName)}</b><small>{text(i.category)} · Prioridad {n(i.priority)}{text(i.lastError)?` · Nota: ${text(i.lastError)}`:''}</small></td><td>{methodLabel(i.method)}</td><td><span className={`cb24-status ${statusClass(i.status)}`}>{statusLabels[String(i.status)]||text(i.status)}</span></td><td><span className={`cb24-status ${qa.code==='approved'?'ok':qa.code==='review'?'bad':qa.code==='pending'?'warn':'neutral'}`}>{qa.label}</span></td><td>{text(i.owner)}</td><td>{formatDate(i.submittedAt)}</td><td>{i.nextReviewAt?formatDate(i.nextReviewAt):'—'}</td><td>{ref?<ResourceAction url={ref} label={live?'Abrir ficha':'Abrir comprobante'} onInternal={()=>onReference(i,live?'listing':'submission')}/>: '—'}</td><td>{rows(i.evidence).length?<span className="cb24-good"><FileCheck2 size={14}/>{rows(i.evidence).length}</span>:'—'}</td><td><button className="cb24-icon-btn" title="Abrir inteligencia del envío" onClick={()=>onOpen(i)}><ExternalLink size={15}/></button></td></tr>})}</tbody></table>{!visible.length?<div className="cb24-empty"><Send size={28}/><p>No hay envíos que coincidan con los filtros.</p></div>:null}</div></div>}
function RequiredActions({actions,onResolve,onAction}:{actions:Row[];onResolve:(a:Row)=>void;onAction:(t:string,d:string)=>void}){return <div className="cb24-action-grid">{actions.map(a=><div className="cb24-action-card" key={String(a.id)}><AlertTriangle/><div><span>REQUIERE ACCIÓN</span><h3>{text(a.directoryName)}</h3><b>{text(a.title)}</b><p>{text(a.instructions)}</p><small>Creada {formatDate(a.createdAt)}</small></div><div><button className="util-btn" onClick={()=>onAction(`Citation Builder · ${text(a.directoryName)}`,text(a.instructions))}>Crear acción SEOLOCAL</button><button className="util-btn primary" onClick={()=>void onResolve(a)}>Marcar resuelta</button></div></div>)}{!actions.length?<div className="cb24-empty"><CheckCircle2 size={30}/><h3>Sin acciones requeridas</h3><p>No hay verificaciones ni documentación pendientes.</p></div>:null}</div>}
function EvidenceCenter({evidence,onPreview,onQa}:{evidence:Row[];onPreview:(e:Row)=>void;onQa:(e:Row)=>void}){return <div className="cb24-evidence-grid">{evidence.map(e=>{const live=String(e.linkKind)==='live_listing'||isLiveStatus(e.submissionStatus);const recordedBy=text(e.recordedBy||e.verifiedBy,'Sistema');const qaBy=text(e.qaVerifiedBy,'');return <div className="cb24-evidence-card" key={String(e.id)}><FileImage/><div><div className="cb24-evidence-top"><span>{evidenceTypeLabels[String(e.type)]||'Evidencia'}</span><span className={`cb24-status ${String(e.qaStatus)==='approved'?'ok':String(e.qaStatus)==='review'?'bad':'neutral'}`}>{String(e.qaStatus)==='approved'?'QA aprobado':String(e.qaStatus)==='review'?'QA con incidencia':'QA pendiente'}</span></div><h3>{text(e.directoryName)}</h3><b>{text(e.title)}</b><div className="cb24-evidence-meta"><span>NAP: <strong>{text(e.napVerified,'Pendiente de QA')}</strong></span><span>Publicación: <strong>{statusLabels[String(e.submissionStatus)]||text(e.submissionStatus)}</strong></span><span>Registrado por: <strong>{recordedBy}</strong></span><span>Fecha: <strong>{formatDate(e.createdAt)}</strong></span>{qaBy?<span>QA por: <strong>{qaBy}</strong></span>:null}{e.qaVerifiedAt?<span>Fecha QA: <strong>{formatDate(e.qaVerifiedAt)}</strong></span>:null}</div>{text(e.note)?<p>{text(e.note)}</p>:null}<div className="cb24-evidence-links">{live&&e.liveUrl?<ResourceAction url={e.liveUrl} label="URL activa" onInternal={()=>onPreview({...e,previewKind:'listing',resourceUrl:e.liveUrl})}/>:null}{!live&&e.submissionReferenceUrl?<ResourceAction url={e.submissionReferenceUrl} label="Comprobante de envío" onInternal={()=>onPreview({...e,previewKind:'submission',resourceUrl:e.submissionReferenceUrl})}/>:null}{e.url?<ResourceAction url={e.url} label="Abrir evidencia" onInternal={()=>onPreview({...e,previewKind:'evidence',resourceUrl:e.url})}/>:null}<button type="button" className="cb24-resource-link secondary" onClick={()=>onQa(e)}><ClipboardCheck size={13}/>Revisar / ejecutar QA</button></div></div></div>})}{!evidence.length?<div className="cb24-empty"><FileImage size={30}/><p>La evidencia de envíos aparecerá aquí.</p></div>:null}</div>}
function Duplicates({items,trackerDuplicates,onImport,onAdd,onStatus}:{items:Row[];trackerDuplicates:Row[];onImport:()=>void;onAdd:()=>void;onStatus:(d:Row,s:string)=>void}){const labels:Record<string,string>={detected:'Detectado',claiming:'Preparando evidencia',submitted:'Solicitud enviada',waiting:'Esperando directorio',removed:'Eliminado',dismissed:'Descartado'};return <div><div className="cb24-panel-head inline"><div><span>RESOLUCIÓN DE DUPLICADOS</span><h3>Tracker detecta → Builder ejecuta → Evidencia confirma</h3><p>{trackerDuplicates.length} duplicado(s) abiertos disponibles desde Citation Tracker.</p></div><div><button className="util-btn" disabled={!trackerDuplicates.length} onClick={()=>void onImport()}><Upload size={15}/>Importar duplicados</button><button className="util-btn primary" onClick={onAdd}><Plus size={15}/>Añadir tarea</button></div></div><div className="cb24-duplicate-list">{items.map(d=><div key={String(d.id)}><div><b>{text(d.directoryName)}</b><span className={`cb24-status ${['removed','dismissed'].includes(String(d.status))?'ok':'warn'}`}>{labels[String(d.status)]||text(d.status)}</span><p>{text(d.note)}</p><small>{text(d.primaryUrl)} → {text(d.duplicateUrl)}</small></div><div className="cb24-duplicate-actions">{!['removed','dismissed'].includes(String(d.status))?<><button className="util-btn" onClick={()=>void onStatus(d,'claiming')}>Preparar evidencia</button><button className="util-btn" onClick={()=>void onStatus(d,'submitted')}>Solicitud enviada</button><button className="util-btn" onClick={()=>void onStatus(d,'waiting')}>Esperando directorio</button><button className="util-btn primary" onClick={()=>void onStatus(d,'removed')}>Eliminado</button></>:<button className="util-btn" onClick={()=>void onStatus(d,'detected')}>Reabrir</button>}</div></div>)}</div>{!items.length&&!trackerDuplicates.length?<div className="cb24-empty"><CheckCircle2 size={28}/><p>No hay duplicados en resolución para esta campaña.</p></div>:null}</div>}
function HistoryTab({timeline,credentials,onCredential}:{timeline:Row[];credentials:Row[];onCredential:()=>void}){const ordered=[...timeline].sort((a,b)=>Date.parse(String(b.at||0))-Date.parse(String(a.at||0)));return <div className="cb24-grid2"><div className="cb24-card"><div className="cb24-section-title"><span>HISTORIAL</span><h3>Línea de tiempo de campaña</h3></div>{ordered.map(t=><div className="cb24-timeline-row" key={String(t.id)}><span/><div><b>{text(t.title)}</b><p>{text(t.detail)}</p></div><time>{formatDate(t.at)}</time></div>)}</div><div className="cb24-card"><div className="cb24-panel-head inline"><div><span>VAULT DE CREDENCIALES</span><h3>Referencias seguras</h3></div><button className="util-btn" onClick={onCredential}><KeyRound size={15}/>Registrar</button></div><p className="cb24-help">Las contraseñas no se muestran ni se guardan en los reportes visibles. Solo se conserva una referencia segura del Vault.</p>{credentials.length?<div className="cb24-vault-table"><div className="cb24-vault-head"><span>Directorio</span><span>Usuario / email</span><span>Tipo</span><span>Referencia</span><span>Actualizado</span><span/></div>{credentials.map(c=><div className="cb24-credential" key={String(c.id)}><b>{text(c.directoryName)}</b><span>{text(c.username)}</span><span>{text(c.label,'General')}</span><code>{text(c.secretReference)}</code><small>{formatDate(c.updatedAt)}</small><div><button title="Copiar usuario" onClick={()=>void navigator.clipboard?.writeText(String(c.username||''))}><Copy size={14}/></button><button title="Copiar referencia Vault" onClick={()=>void navigator.clipboard?.writeText(String(c.secretReference||''))}><KeyRound size={14}/></button></div></div>)}</div>:<div className="cb24-empty compact"><KeyRound size={25}/><p>Aún no hay referencias de credenciales registradas.</p></div>}</div></div>}

function ProfileModal({draft,setDraft,onSubmit,onClose}:{draft:Row;setDraft:(r:Row)=>void;onSubmit:(e:FormEvent)=>void;onClose:()=>void}){const csv=(key:string,value:string)=>setDraft({...draft,[key]:value.split(',').map(x=>x.trim()).filter(Boolean)});return <Modal title="Datos del negocio para envíos" onClose={onClose} wide footer={<button form="cb24-profile" className="util-btn primary">Guardar dataset</button>}><form id="cb24-profile" onSubmit={onSubmit} className="cb24-form grid">{[['name','Nombre'],['address','Dirección'],['phone','Teléfono'],['postcode','Código postal'],['website','Sitio web'],['email','Email'],['contactName','Contacto'],['primaryCategory','Categoría principal'],['description','Descripción'],['additionalInfo','Datos adicionales / licencia'],['campaignNotes','Notas de campaña']].map(([k,l])=><label className={['address','description','additionalInfo','campaignNotes'].includes(k)?'wide':''} key={k}>{l}{['description','additionalInfo','campaignNotes'].includes(k)?<textarea value={String(draft[k]||'')} onChange={e=>setDraft({...draft,[k]:e.target.value})}/>:<input required={['name','address','phone'].includes(k)} value={String(draft[k]||'')} onChange={e=>setDraft({...draft,[k]:e.target.value})}/>}</label>)}<label className="wide">Categorías secundarias<input value={rows(draft.secondaryCategories).join(', ')} onChange={e=>csv('secondaryCategories',e.target.value)}/></label><label className="wide">Servicios<input value={rows(draft.services).join(', ')} onChange={e=>csv('services',e.target.value)}/></label><label className="wide">Métodos de pago<input value={rows(draft.paymentMethods).join(', ')} onChange={e=>csv('paymentMethods',e.target.value)}/></label><label className="wide">Logo URL<input value={String(draft.logoUrl||'')} onChange={e=>setDraft({...draft,logoUrl:e.target.value})}/></label><label className="wide">Imágenes (URLs separadas por coma)<input value={rows(draft.imageUrls).join(', ')} onChange={e=>csv('imageUrls',e.target.value)}/></label><label className="wide">Redes sociales (formato clave=url, separadas por coma)<input value={Object.entries(rec(draft.socialProfiles)).map(([k,v])=>`${k}=${String(v)}`).join(', ')} onChange={e=>{const social:Row={};e.target.value.split(',').map(x=>x.trim()).filter(Boolean).forEach(pair=>{const [k,...rest]=pair.split('=');if(k&&rest.length)social[k.trim()]=rest.join('=').trim()});setDraft({...draft,socialProfiles:social})}}/></label><label className="wide">Horarios (ej. lunes=08:00-18:00)<input value={Object.entries(rec(draft.hours)).map(([k,v])=>`${k}=${String(v)}`).join(', ')} onChange={e=>{const hours:Row={};e.target.value.split(',').map(x=>x.trim()).filter(Boolean).forEach(pair=>{const [k,...rest]=pair.split('=');if(k&&rest.length)hours[k.trim()]=rest.join('=').trim()});setDraft({...draft,hours})}}/></label></form></Modal>}
function DirectoryModal({draft,setDraft,onSubmit,onClose}:{draft:Row;setDraft:(r:Row)=>void;onSubmit:(e:FormEvent)=>void;onClose:()=>void}){return <Modal title="Añadir directorio" onClose={onClose} footer={<button className="util-btn primary" form="cb24-directory">Añadir</button>}><form id="cb24-directory" onSubmit={onSubmit} className="cb24-form"><label>Directorio<input required value={String(draft.directoryName||'')} onChange={e=>setDraft({...draft,directoryName:e.target.value})}/></label><label>URL<input value={String(draft.directoryUrl||'')} onChange={e=>setDraft({...draft,directoryUrl:e.target.value})}/></label><label>Método<select value={String(draft.method||'manual')} onChange={e=>setDraft({...draft,method:e.target.value})}><option value="manual">Manual</option><option value="api">API</option><option value="network">Network/Aggregator</option></select></label><label>Tipo<select value={String(draft.pricing||'free')} onChange={e=>setDraft({...draft,pricing:e.target.value})}><option value="free">Gratis</option><option value="paid">Pago</option></select></label><label>Autoridad<input type="number" min="0" value={String(draft.authority||60)} onChange={e=>setDraft({...draft,authority:Number(e.target.value)})}/></label><label>Prioridad<input type="number" min="0" value={String(draft.priority||60)} onChange={e=>setDraft({...draft,priority:Number(e.target.value)})}/></label></form></Modal>}
function ItemModal({item,draft,setDraft,onClose,onStatus,onEvidence,onRequired,onQa}:{item:Row;draft:Row;setDraft:(r:Row)=>void;onClose:()=>void;onStatus:(s:string)=>void;onEvidence:()=>void;onRequired:()=>void;onQa:()=>void}){const qa=qaStatus(item);const live=isLiveStatus(item.status);return <Modal title={`Inteligencia del envío · ${text(item.directoryName)}`} onClose={onClose} wide footer={<button className="util-btn" onClick={onClose}>Cerrar</button>}><div className="cb24-item-detail"><div className="cb24-item-banner"><div><small>PUBLICACIÓN</small><b>{statusLabels[String(item.status)]||text(item.status)}</b></div><div className={`cb24-qa-badge ${qa.code}`}><small>CONTROL QA</small><b>{qa.label}</b><span>{qa.score}</span></div></div><div className="cb24-profile-grid"><div><small>Método</small><strong>{methodLabel(item.method)}</strong></div><div><small>Responsable</small><strong>{text(item.owner)}</strong></div><div><small>Prioridad</small><strong>{n(item.priority)}</strong></div><div><small>Autoridad</small><strong>{n(item.authority)}</strong></div><div><small>Requisitos</small><strong>{rows(item.requirements).join(', ')||'Sin requisitos'}</strong></div><div><small>Enviado</small><strong>{formatDate(item.submittedAt)}</strong></div><div><small>Próxima revisión</small><strong>{item.nextReviewAt?formatDate(item.nextReviewAt):'—'}</strong></div><div><small>Evidencias</small><strong>{rows(item.evidence).length}</strong></div></div><label>{live?'URL de ficha activa':'URL / referencia de envío'}<input value={String(draft.listingUrl||'')} onChange={e=>setDraft({...draft,listingUrl:e.target.value})}/></label><label>Nota / incidencia<textarea value={String(draft.note||'')} onChange={e=>setDraft({...draft,note:e.target.value})}/></label><div className="cb24-item-actions"><button className="util-btn" onClick={()=>void onStatus('ready')}>Lista</button><button className="util-btn" onClick={()=>void onStatus('submitted')}>Enviar</button><button className="util-btn" onClick={()=>void onStatus('verification')}>Verificación</button><button className="util-btn" onClick={onRequired}>Requiere acción</button><button className="util-btn" onClick={()=>void onStatus('live')}>Marcar activa</button><button className="util-btn primary" onClick={onQa}>Ejecutar QA</button><button className="util-btn" onClick={onEvidence}>Añadir evidencia</button></div><p className="cb24-help">El estado de publicación y el QA son dimensiones independientes: una ficha puede estar activa mientras su QA sigue pendiente.</p></div></Modal>}
function ResourcePreviewModal({resource,item,onClose,onQa}:{resource:Row;item:Row|null;onClose:()=>void;onQa:(item:Row)=>void}){const kind=String(resource.previewKind||'evidence');const url=String(resource.resourceUrl||resource.url||resource.listingUrl||resource.evidenceUrl||'');const qa=item?qaStatus(item):{code:String(resource.qaStatus||'pending'),label:String(resource.qaStatus)==='approved'?'QA aprobado':String(resource.qaStatus)==='review'?'QA con incidencia':'QA pendiente',score:text(resource.napVerified,'Pendiente')};const title=kind==='listing'?'Vista de ficha Local Lab':kind==='submission'?'Comprobante de envío Local Lab':'Visor interno de evidencia';const directory=text(resource.directoryName||item?.directoryName,'Directorio Local Lab');return <Modal title={title} onClose={onClose} wide footer={<div className="cb24-preview-footer">{item?<button className="util-btn primary" onClick={()=>onQa(item)}><ClipboardCheck size={15}/>Ejecutar QA</button>:null}<button className="util-btn" onClick={onClose}>Cerrar</button></div>}><div className="cb24-resource-preview"><div className="cb24-preview-notice"><ShieldCheck size={19}/><div><b>Recurso de laboratorio protegido</b><span>Esta referencia pertenece a Local Lab y se previsualiza dentro de SEOLOCAL. No se intenta abrir un dominio ficticio fuera de la aplicación.</span></div></div><div className="cb24-preview-head"><div><small>{kind==='evidence'?'EVIDENCIA':kind==='listing'?'FICHA ACTIVA':'COMPROBANTE DE ENVÍO'}</small><h3>{directory}</h3><p>{text(resource.title||resource.note,kind==='listing'?'Ficha simulada para validación funcional.':'Referencia operativa Local Lab.')}</p></div><span className={`cb24-status ${qa.code==='approved'?'ok':qa.code==='review'?'bad':qa.code==='pending'?'warn':'neutral'}`}>{qa.label}</span></div><div className="cb24-preview-grid"><div><small>Publicación</small><strong>{statusLabels[String(resource.submissionStatus||item?.status)]||text(resource.submissionStatus||item?.status,'—')}</strong></div><div><small>NAP / QA</small><strong>{text(resource.napVerified||qa.score,'Pendiente')}</strong></div><div><small>Registrado por</small><strong>{text(resource.recordedBy||resource.verifiedBy,'Sistema')}</strong></div><div><small>QA por</small><strong>{text(resource.qaVerifiedBy||rec(item?.qa).verifiedBy,'Pendiente')}</strong></div><div><small>Fecha del recurso</small><strong>{formatDate(resource.createdAt||item?.submittedAt)}</strong></div><div><small>Fecha QA</small><strong>{resource.qaVerifiedAt||rec(item?.qa).verifiedAt?formatDate(resource.qaVerifiedAt||rec(item?.qa).verifiedAt):'Pendiente'}</strong></div></div><div className="cb24-preview-reference"><small>REFERENCIA TÉCNICA LOCAL LAB</small><code>{url||'Sin URL de referencia'}</code><p>Esta cadena se conserva como evidencia técnica y trazabilidad del laboratorio; no implica que exista una página pública en ese dominio.</p></div>{text(resource.note)?<div className="cb24-preview-note"><small>NOTA</small><p>{text(resource.note)}</p></div>:null}</div></Modal>}
function EvidenceModal({draft,setDraft,onSubmit,onClose}:{draft:Row;setDraft:(r:Row)=>void;onSubmit:(e:FormEvent)=>void;onClose:()=>void}){return <Modal title="Registrar evidencia" onClose={onClose} footer={<button form="cb24-evidence" className="util-btn primary">Guardar evidencia</button>}><form id="cb24-evidence" onSubmit={onSubmit} className="cb24-form"><label>Título<input required value={String(draft.title||'')} onChange={e=>setDraft({...draft,title:e.target.value})}/></label><label>Tipo<select value={String(draft.type||'screenshot')} onChange={e=>setDraft({...draft,type:e.target.value})}><option value="screenshot">Captura</option><option value="listing">Ficha</option><option value="email">Email</option><option value="document">Documento</option><option value="other">Otro</option></select></label><label>URL<input value={String(draft.url||'')} onChange={e=>setDraft({...draft,url:e.target.value})}/></label><label>Nota<textarea value={String(draft.note||'')} onChange={e=>setDraft({...draft,note:e.target.value})}/></label></form></Modal>}
function RequiredModal({draft,setDraft,onSubmit,onClose}:{draft:Row;setDraft:(r:Row)=>void;onSubmit:(e:FormEvent)=>void;onClose:()=>void}){return <Modal title="Acción requerida" onClose={onClose} footer={<button form="cb24-required" className="util-btn primary">Crear bloqueo</button>}><form id="cb24-required" onSubmit={onSubmit} className="cb24-form"><label>Título<input required value={String(draft.title||'')} onChange={e=>setDraft({...draft,title:e.target.value})}/></label><label>Instrucciones<textarea value={String(draft.instructions||'')} onChange={e=>setDraft({...draft,instructions:e.target.value})}/></label></form></Modal>}
function QaModal({draft,setDraft,onSubmit,onClose}:{draft:Row;setDraft:(r:Row)=>void;onSubmit:(e:FormEvent)=>void;onClose:()=>void}){const checks=[['qaName','Nombre'],['qaAddress','Dirección'],['qaPhone','Teléfono'],['qaWebsite','Website'],['qaCategory','Categoría']];return <Modal title="QA de publicación" onClose={onClose} footer={<button form="cb24-qa" className="util-btn primary">Guardar QA</button>}><form id="cb24-qa" onSubmit={onSubmit} className="cb24-qa-form">{checks.map(([k,l])=><label key={k}><input type="checkbox" checked={Boolean(draft[k])} onChange={e=>setDraft({...draft,[k]:e.target.checked})}/>{l}</label>)}<label>Nota<textarea value={String(draft.note||'')} onChange={e=>setDraft({...draft,note:e.target.value})}/></label></form></Modal>}
function DuplicateModal({draft,setDraft,onSubmit,onClose}:{draft:Row;setDraft:(r:Row)=>void;onSubmit:(e:FormEvent)=>void;onClose:()=>void}){return <Modal title="Nueva tarea de duplicado" onClose={onClose} footer={<button form="cb24-dup" className="util-btn primary">Guardar tarea</button>}><form id="cb24-dup" onSubmit={onSubmit} className="cb24-form"><label>Directorio<input required value={String(draft.directoryName||'')} onChange={e=>setDraft({...draft,directoryName:e.target.value})}/></label><label>Ficha principal<input value={String(draft.primaryUrl||'')} onChange={e=>setDraft({...draft,primaryUrl:e.target.value})}/></label><label>Duplicado<input value={String(draft.duplicateUrl||'')} onChange={e=>setDraft({...draft,duplicateUrl:e.target.value})}/></label><label>Nota<textarea value={String(draft.note||'')} onChange={e=>setDraft({...draft,note:e.target.value})}/></label></form></Modal>}
function ReportModal({onClose,onCsv,onPrint,onCopy}:{onClose:()=>void;onCsv:()=>void;onPrint:()=>void;onCopy:()=>void}){return <Modal title="Reporte de campaña" onClose={onClose} footer={<button className="util-btn" onClick={onClose}>Cerrar</button>}><div className="cb24-report-actions"><button className="util-btn primary" onClick={onCsv}><Download size={16}/>Descargar CSV</button><button className="util-btn" onClick={onPrint}><Printer size={16}/>Imprimir / guardar PDF</button><button className="util-btn" onClick={()=>void onCopy()}><Link2 size={16}/>Copiar enlace interno</button></div><p className="cb24-help">El enlace interno requiere autenticación en SEOLOCAL. La opción de impresión permite guardar el reporte como PDF desde el navegador.</p></Modal>}
function CredentialModal({draft,setDraft,onSubmit,onClose}:{draft:Row;setDraft:(r:Row)=>void;onSubmit:(e:FormEvent)=>void;onClose:()=>void}){return <Modal title="Registrar referencia de credencial" onClose={onClose} footer={<button form="cb24-credential" className="util-btn primary">Registrar</button>}><form id="cb24-credential" onSubmit={onSubmit} className="cb24-form"><label>Directorio<input required value={String(draft.directoryName||'')} onChange={e=>setDraft({...draft,directoryName:e.target.value})}/></label><label>Usuario / email<input required value={String(draft.username||'')} onChange={e=>setDraft({...draft,username:e.target.value})}/></label><label>Etiqueta<input value={String(draft.label||'')} onChange={e=>setDraft({...draft,label:e.target.value})}/></label><p className="cb24-help"><ShieldCheck size={15}/>Por seguridad esta pantalla no solicita ni devuelve contraseñas; se registra una referencia de vault.</p></form></Modal>}
